/* Landing page — Kopec Coffee Roasters, Brno.
 * Spacing, radii and font stacks come from the maude tokens; the palette is
 * opted out (@opt_out palette) for a warm, light roastery brand. */

.lp {
  --lp-paper: #f6f0e6;
  --lp-paper-2: #ede4d5;
  --lp-card: #fffaf2;
  --lp-ink: #2a1d15;
  --lp-ink-2: #5b4a3e;
  --lp-line: #dccfbc;
  --lp-roast: #8a3b1f;
  --lp-roast-ink: #fff6ec;
  --lp-crema: #c98a4b;
  --lp-night: #1f1611;

  background: var(--lp-paper);
  color: var(--lp-ink);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.55;
  width: 100%;
  min-height: 100%;
}
.lp * { box-sizing: border-box; }
.lp h1, .lp h2, .lp h3 { font-family: var(--font-display); margin: 0; letter-spacing: var(--tracking-tight); line-height: 1.08; }
.lp p { margin: 0; }
.lp a { color: inherit; }

.lp-wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--space-8); }
.lp-eyebrow { font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--lp-roast); }

.lp-skip { position: absolute; left: -9999px; }
.lp-skip:focus { left: var(--space-5); top: var(--space-5); background: var(--lp-ink); color: var(--lp-paper); padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); }

/* Buttons */
.lp-btn { display: inline-flex; align-items: center; gap: var(--space-3); min-height: 48px; padding: 0 var(--space-6); border-radius: var(--radius-pill); font-weight: 600; font-size: 16px; text-decoration: none; border: 1.5px solid transparent; }
.lp-btn--primary { background: var(--lp-roast); color: var(--lp-roast-ink); }
.lp-btn--ghost { border-color: var(--lp-ink); color: var(--lp-ink); }
.lp-btn:focus-visible { outline: 3px solid var(--lp-crema); outline-offset: 3px; }

/* Nav */
.lp-nav { display: flex; align-items: center; justify-content: space-between; height: 80px; }
.lp-brand { display: flex; align-items: center; gap: var(--space-3); font-family: var(--font-display); font-weight: 700; font-size: 20px; text-decoration: none; }
.lp-nav ul { display: flex; gap: var(--space-7); list-style: none; margin: 0; padding: 0; font-weight: 500; }
.lp-nav ul a { text-decoration: none; }
.lp-nav-cta { min-height: 40px; padding: 0 var(--space-5); font-size: 15px; }

/* Hero */
.lp-hero { display: grid; grid-template-columns: 1.05fr 1fr; gap: var(--space-8); align-items: center; padding: var(--space-8) 0 96px; }
.lp-hero h1 { font-size: 76px; font-weight: 700; margin-top: var(--space-5); }
.lp-hero h1 em { font-style: normal; color: var(--lp-roast); }
.lp-hero-lede { font-size: 20px; color: var(--lp-ink-2); max-width: 30em; margin-top: var(--space-6); }
.lp-hero-actions { display: flex; flex-wrap: wrap; gap: var(--space-4); margin-top: var(--space-7); }
.lp-hero-art { position: relative; aspect-ratio: 1 / 1.05; border-radius: 28px; overflow: hidden; background: radial-gradient(120% 90% at 30% 20%, #a5532c 0%, #6b2c16 45%, var(--lp-night) 100%); }
.lp-hero-art svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.lp-hero-tag { position: absolute; left: var(--space-6); bottom: var(--space-6); background: var(--lp-card); border-radius: var(--radius-xl); padding: var(--space-4) var(--space-5); box-shadow: 0 10px 30px rgb(31 22 17 / 0.25); }
.lp-hero-tag strong { display: block; font-family: var(--font-display); font-size: 18px; }
.lp-hero-tag span { font-size: 14px; color: var(--lp-ink-2); }

/* Roast-day strip */
.lp-strip { background: var(--lp-ink); color: var(--lp-paper); }
.lp-strip .lp-wrap { display: flex; justify-content: space-between; gap: var(--space-6); padding-top: var(--space-6); padding-bottom: var(--space-6); }
.lp-strip-item { display: flex; align-items: baseline; gap: var(--space-3); }
.lp-strip-item b { font-family: var(--font-mono); font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--lp-crema); }

/* Sections */
.lp-section { padding: 112px 0; }
.lp-section-head { display: flex; justify-content: space-between; align-items: end; gap: var(--space-7); margin-bottom: var(--space-8); }
.lp-section-head h2 { font-size: 48px; margin-top: var(--space-4); max-width: 14em; }
.lp-section-head p { color: var(--lp-ink-2); max-width: 26em; }

/* Beans */
.lp-beans { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.lp-bean { background: var(--lp-card); border: 1px solid var(--lp-line); border-radius: 20px; overflow: hidden; display: flex; flex-direction: column; }
.lp-bean-swatch { height: 168px; position: relative; }
.lp-bean-swatch span { position: absolute; top: var(--space-5); left: var(--space-5); font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; background: rgb(255 250 242 / 0.92); color: var(--lp-ink); padding: var(--space-2) var(--space-3); border-radius: var(--radius-pill); }
.lp-bean-body { padding: var(--space-6); display: flex; flex-direction: column; gap: var(--space-4); flex: 1; }
.lp-bean h3 { font-size: 26px; }
.lp-bean-origin { font-size: 15px; color: var(--lp-ink-2); }
.lp-notes { display: flex; flex-wrap: wrap; gap: var(--space-3); list-style: none; margin: 0; padding: 0; }
.lp-notes li { font-size: 14px; padding: var(--space-1) var(--space-4); border: 1px solid var(--lp-line); border-radius: var(--radius-pill); }
.lp-bean-foot { display: flex; justify-content: space-between; align-items: center; margin-top: auto; padding-top: var(--space-4); border-top: 1px solid var(--lp-line); }
.lp-price { font-family: var(--font-display); font-weight: 700; font-size: 20px; }
.lp-price small { font-family: var(--font-body); font-weight: 400; font-size: 14px; color: var(--lp-ink-2); }
.lp-add { min-height: 44px; padding: 0 var(--space-5); font-size: 15px; }

/* Process */
.lp-process { background: var(--lp-paper-2); }
.lp-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-7); list-style: none; margin: 0; padding: 0; counter-reset: step; }
.lp-steps li { border-top: 2px solid var(--lp-ink); padding-top: var(--space-6); }
.lp-steps li::before { counter-increment: step; content: "0" counter(step); font-family: var(--font-mono); font-size: 13px; color: var(--lp-roast); display: block; margin-bottom: var(--space-4); }
.lp-steps h3 { font-size: 24px; margin-bottom: var(--space-4); }
.lp-steps p { color: var(--lp-ink-2); }

/* Subscription */
.lp-sub { display: grid; grid-template-columns: 1.2fr 1fr; gap: var(--space-8); align-items: center; background: var(--lp-roast); color: var(--lp-roast-ink); border-radius: 32px; padding: 72px; }
.lp-sub .lp-eyebrow { color: #f3c99a; }
.lp-sub h2 { font-size: 48px; margin-top: var(--space-4); }
.lp-sub p { margin-top: var(--space-5); color: #f6dcc4; font-size: 18px; }
.lp-sub-plans { display: grid; gap: var(--space-4); }
.lp-plan { display: flex; justify-content: space-between; align-items: center; background: rgb(255 246 236 / 0.1); border: 1px solid rgb(255 246 236 / 0.28); border-radius: var(--radius-xl); padding: var(--space-5) var(--space-6); }
.lp-plan strong { font-family: var(--font-display); font-size: 19px; display: block; }
.lp-plan span { font-size: 14px; color: #f6dcc4; }
.lp-plan b { font-family: var(--font-display); font-size: 20px; white-space: nowrap; }
.lp-sub .lp-btn--primary { background: var(--lp-roast-ink); color: var(--lp-roast); margin-top: var(--space-7); }

/* Visit */
.lp-visit { display: grid; grid-template-columns: 1fr 1.1fr; gap: var(--space-8); align-items: stretch; }
.lp-visit h2 { font-size: 48px; margin-top: var(--space-4); }
.lp-visit-lede { color: var(--lp-ink-2); margin-top: var(--space-5); }
.lp-hours { margin: var(--space-7) 0 0; display: grid; grid-template-columns: auto 1fr; gap: var(--space-3) var(--space-7); }
.lp-hours dt { font-weight: 600; }
.lp-hours dd { margin: 0; color: var(--lp-ink-2); font-variant-numeric: tabular-nums; }
.lp-address { font-style: normal; margin-top: var(--space-7); font-size: 18px; }
.lp-map { border-radius: 24px; border: 1px solid var(--lp-line); overflow: hidden; background: var(--lp-paper-2); position: relative; min-height: 420px; }
.lp-map svg { position: absolute; inset: 0; width: 100%; height: 100%; }

/* Footer */
.lp-footer { background: var(--lp-night); color: #d9cbbb; padding: 72px 0 var(--space-8); }
.lp-footer-grid { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: var(--space-7); }
.lp-footer h3 { font-size: 15px; color: var(--lp-paper); margin-bottom: var(--space-4); font-family: var(--font-body); letter-spacing: 0; }
.lp-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--space-3); font-size: 15px; }
.lp-footer ul a { text-decoration: none; }
.lp-footer .lp-brand { color: var(--lp-paper); }
.lp-footer-note { margin-top: var(--space-5); font-size: 15px; max-width: 22em; }
.lp-footer-base { margin-top: 56px; padding-top: var(--space-6); border-top: 1px solid rgb(217 203 187 / 0.2); font-size: 14px; display: flex; justify-content: space-between; }

/* ── Mobile (390) ───────────────────────────────────────────────────────── */
.lp--mobile { font-size: 16px; }
.lp--mobile .lp-wrap { padding: 0 var(--space-5); }
.lp--mobile .lp-nav { height: 64px; }
.lp--mobile .lp-nav ul { display: none; }
.lp--mobile .lp-menu { display: inline-flex; }
.lp-menu { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; border-radius: var(--radius-pill); border: 1.5px solid var(--lp-ink); background: transparent; color: var(--lp-ink); }
.lp--mobile .lp-hero { grid-template-columns: 1fr; gap: var(--space-7); padding: var(--space-6) 0 64px; }
.lp--mobile .lp-hero h1 { font-size: 44px; }
.lp--mobile .lp-hero-lede { font-size: 17px; }
.lp--mobile .lp-hero-actions .lp-btn { flex: 1 1 100%; justify-content: center; }
.lp--mobile .lp-hero-art { aspect-ratio: 1 / 0.9; border-radius: 22px; }
.lp--mobile .lp-strip .lp-wrap { flex-direction: column; gap: var(--space-3); }
.lp--mobile .lp-section { padding: 72px 0; }
.lp--mobile .lp-section-head { flex-direction: column; align-items: start; gap: var(--space-4); margin-bottom: var(--space-7); }
.lp--mobile .lp-section-head h2,
.lp--mobile .lp-sub h2,
.lp--mobile .lp-visit h2 { font-size: 34px; }
.lp--mobile .lp-beans,
.lp--mobile .lp-steps,
.lp--mobile .lp-sub,
.lp--mobile .lp-visit { grid-template-columns: 1fr; }
.lp--mobile .lp-steps { gap: var(--space-6); }
.lp--mobile .lp-sub { padding: var(--space-7) var(--space-6); border-radius: 24px; gap: var(--space-7); }
.lp--mobile .lp-sub .lp-btn--primary { width: 100%; justify-content: center; }
.lp--mobile .lp-map { min-height: 280px; }
.lp--mobile .lp-footer-grid { grid-template-columns: 1fr 1fr; }
.lp--mobile .lp-footer-grid > :first-child { grid-column: 1 / -1; }
.lp--mobile .lp-footer-base { flex-direction: column; gap: var(--space-3); }

